curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{"query":"{ a: __type(name: \"Query\") { fields { name args { name type { name kind ofType { name } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['a']['fields']:
    if f['name'] in ('projects','teams','documents','projectLabels','issueLabels'):
        print(f['name'])
        for a in f['args']:
            t=a['type']; tn=t['name'] or (t.get('ofType') or {}).get('name','?')
            print('   ', a['name'], tn, 'required' if t['kind']=='NON_NULL' else '')
"

